CREATE TABLE push_devices(installation_id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_users(id),family_id uuid NOT NULL,token text NOT NULL UNIQUE,enabled boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX push_devices_owner ON push_devices(user_id) WHERE enabled;
CREATE TABLE push_deliveries(event_id bigint NOT NULL REFERENCES events(id),installation_id uuid NOT NULL REFERENCES push_devices(installation_id),user_id uuid NOT NULL REFERENCES app_users(id),family_id uuid NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','sent','cancelled','failed')),attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_token uuid,last_error text,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(event_id,installation_id));
CREATE INDEX push_deliveries_due ON push_deliveries(next_attempt_at,event_id) WHERE status IN ('pending','sending');
